/**
 * Conformance tests for the SDK DMN parser.
 *
 * Each test parses a specific `.dmn` fixture with the TypeScript parser and
 * deep-compares the result against a golden JSON snapshot generated by the
 * Elixir parser (`scripts/generate-dmn-parser-snapshots.exs`).
 *
 * Fixture directory (relative to the engine project root):
 *   - apps/core_dmn/test/fixtures/dmns/
 */
import { readFileSync, readdirSync } from 'node:fs';
import { join, resolve } from 'node:path';
import { describe, expect, it } from 'vitest';

import { parseDmn } from '../../src/index.js';

const PROJECT_ROOT = resolve(__dirname, '../../../../..');
const SNAPSHOT_DIR = resolve(__dirname, 'snapshots/dmn');
const CORE_FIXTURES = join(PROJECT_ROOT, 'apps/core_dmn/test/fixtures/dmns');

function loadFixture(name: string): string {
  return readFileSync(join(CORE_FIXTURES, `${name}.dmn`), 'utf-8');
}

function loadSnapshot(name: string): unknown {
  return JSON.parse(readFileSync(join(SNAPSHOT_DIR, `${name}.json`), 'utf-8'));
}

function sortKeys(value: unknown): unknown {
  if (value === null || value === undefined) {
    return value;
  }
  if (Array.isArray(value)) {
    return value.map(sortKeys);
  }
  if (typeof value === 'object') {
    const sorted: Record<string, unknown> = {};
    for (const key of Object.keys(value as Record<string, unknown>).sort()) {
      sorted[key] = sortKeys((value as Record<string, unknown>)[key]);
    }
    return sorted;
  }
  return value;
}

/**
 * Keys that exist only in the Elixir model (precompiler artefacts, runtime
 * indices) and must be stripped from snapshots before comparison.
 */
const ELIXIR_ONLY_KEYS = new Set(['compiledInputValuesRef', 'compiledDefaultRef', 'ruleIndex']);

/**
 * Normalizes parser output for cross-parser comparison.
 *
 * Intentional structural differences:
 * 1. `rawXml` — TS includes it, Elixir generator strips it
 * 2. `outputLabel` on decisions — TS derives it from `variable.name`
 *    when present; Elixir only reads the XML `outputLabel` attribute.
 *    When a `variable` is present, we strip `outputLabel` from both
 *    sides since the canonical name lives in `variable.name`.
 * 3. `dmndi` — TS always emits the field (null when absent); Elixir
 *    snapshot generator does not serialize DMNDI at all. Strip from
 *    both sides for comparison.
 * 4. `compiledInputValuesRef`, `compiledDefaultRef`, `ruleIndex` — Elixir
 *    precompiler artefacts that the TS parser does not produce.
 * 5. BKM function definition expressionLanguage: Elixir serializes as
 *    `type` (lowercase), TS uses `kind` (uppercase). Normalize both to
 *    a canonical `_expressionKind` key with lowercase value.
 */
function normalizeForConformance(value: unknown): unknown {
  if (value === null || value === undefined) {
    return value;
  }
  if (Array.isArray(value)) {
    return value.map(normalizeForConformance);
  }
  if (typeof value === 'object') {
    const record = value as Record<string, unknown>;
    const result: Record<string, unknown> = {};
    for (const [key, val] of Object.entries(record)) {
      if (key === 'rawXml') {
        continue;
      }
      if (key === 'dmndi') {
        continue;
      }
      if (ELIXIR_ONLY_KEYS.has(key)) {
        continue;
      }
      if (key === 'outputLabel' && record['variable'] != null) {
        continue;
      }
      if ((key === 'type' || key === 'kind') && 'formalParameters' in record) {
        result['_expressionKind'] = String(val).toLowerCase();
        continue;
      }
      result[key] = normalizeForConformance(val);
    }
    return result;
  }
  return value;
}

function expectConformance(fixtureName: string): void {
  const xml = loadFixture(fixtureName);
  const result = parseDmn(xml);
  const expected = loadSnapshot(fixtureName);

  expect(sortKeys(normalizeForConformance(result))).toEqual(sortKeys(normalizeForConformance(expected)));
}

function snapshotNames(): string[] {
  try {
    return readdirSync(SNAPSHOT_DIR)
      .filter((file) => file.endsWith('.json'))
      .map((file) => file.replace(/\.json$/, ''))
      .sort();
  } catch {
    return [];
  }
}

