// ---------------------------------------------------------------------------
// Completeness guard: every snapshot file has a test
// ---------------------------------------------------------------------------

describe('snapshot completeness', () => {
  it('every snapshot file has a corresponding test', () => {
    const snapshots = snapshotNames();
    expect(snapshots.length).toBeGreaterThan(0);

    const testedFixtures = new Set<string>();

    for (const name of snapshots) {
      try {
        loadFixture(name);
        loadSnapshot(name);
        testedFixtures.add(name);
      } catch {
        // fixture or snapshot missing — will be caught by individual tests
      }
    }

    const untestedSnapshots = snapshots.filter((name) => !testedFixtures.has(name));
    expect(untestedSnapshots).toEqual([]);
  });
});
